with matched_keys as (select event_type, page from web_events intersect select event_type, page from web_events where event_type = 'add_to_cart'), reconciled as (select s.* from web_events s join matched_keys k on s.event_type = k.event_type and s.page = k.page) select s.id, s.session_id, s.event_type, s.page, s.duration_sec, (select avg(t2.duration_sec) from web_events t2 where t2.session_id = s.session_id) as avg_web_event_duration_sec from reconciled s;
